import{c,d as h,e as t}from"./chunk-DV6GONZ6.js";import{b as n,d as r}from"./chunk-FV53KXGL.js";var a=[{title:"About Ocufuse",items:[["What is Ocufuse?","Ocufuse is a daily eye photo journal for web and iPhone. The app guides you through four consistent eye photos, lets you log timed context such as sleep, caffeine, screen time and eye drops, and builds a Doctor Brief you can print or send to your eye doctor before an appointment."],["Is Ocufuse a medical device?","Ocufuse is not a medical device. The app does not diagnose, monitor, treat or prevent any eye condition, and it does not measure eye alignment or label photos as normal or abnormal. It is a personal journal that helps you keep a consistent record to share with a qualified eye care professional."],["How much does Ocufuse cost?","Ocufuse is free during early access. The web app opens first at app.ocufuse.com, and the iPhone app follows on the App Store. If paid features are added later, Ocufuse will show the price before any charge, and App Store purchases will be handled by Apple under its standard terms."],["Is Ocufuse available on iPhone?","The Ocufuse iPhone app is in development and will be released on the App Store. The web app opens first at app.ocufuse.com and works in any modern browser on phone or desktop. When the iPhone app arrives, you sign in with the same account and your photos and entries carry over."],["What is an eye photo journal?","An eye photo journal is a dated series of eye photos taken the same way each day, paired with short notes about what happened. Consistent lighting, distance and views make photos comparable over time. Notes about sleep, screens or eye drops give your eye doctor context for symptoms that come and go."],["Does Ocufuse use my photos to train AI?","Ocufuse does not use your photos or journal entries to train AI or machine learning models. Your data is used only to run the features you use, such as your timeline, comparisons and Doctor Brief. Ocufuse also does not sell data, share it with data brokers, or use it for advertising."],["Which languages does Ocufuse support?","Ocufuse supports English, Albanian, Turkish and Bosnian, with light and dark mode in every language. You can change the language in Settings at any time. Switching language changes the app's interface only, so your eye photos, notes and journal entries stay exactly as you recorded them."],["Can children use Ocufuse?","Ocufuse is for people aged 16 and over, and it does not knowingly collect data from children under 16. Parents managing a child's eye condition should follow their eye care team's advice on records and photos. If a child under 16 has created an account, contact Ocufuse and it will be deleted."],["Is Ocufuse an eye tracker?","Ocufuse is not an eye tracker. Eye trackers are devices or software that follow where a person is looking, often for research or accessibility. Ocufuse does not track gaze or monitor health. It is a photo journal that stores the eye photos and notes you choose to record."],["Where does Ocufuse store my data?","Ocufuse stores account data, eye photos and journal entries in the EU, in Frankfurt, Germany, through its hosting provider Supabase. Photos sit in private storage that only your signed-in account can read. Ocufuse does not sell data, use it for advertising, or train AI models on your photos."],["Can I delete my Ocufuse data?","Ocufuse lets you delete your account and all its data from Settings, then Account, then Delete account. Photos, entries and settings are removed from live systems immediately and from encrypted backups within 30 days. Export a Doctor Brief or CSV first if you want to keep a copy."]]},{title:"Eye photos and appointments",items:[["How do I take a photo of my eye for my doctor?","Take eye photos in soft, even light with the flash off, at a steady distance of about 30 to 40 cm, with your head level. Use the same views each time, such as straight ahead, left, right and up. Ask your clinician whether they want extra views, such as looking down."],["Why do my eye photos look different every day?","Eye photos change mainly because of lighting, camera distance, head angle and automatic phone processing. Tiredness, time of day, screen use, alcohol and allergies can also change how eyes look. A series of photos taken the same way is more meaningful than comparing any two single photos."],["What should I bring to an eye doctor appointment?","Bring your glasses or contact lenses, a list of medications and eye drops, and notes on when symptoms happen and how long they last. For symptoms that come and go, dated photos taken the same way each time help your eye doctor see days you cannot show in person."],["How do I share my Ocufuse journal with my eye doctor?","Ocufuse shares your journal through a Doctor Brief that you export yourself. Open Brief, choose the date range and what to include, then print it, send it as text, or export entries as CSV. Clinicians have no access to your account, and nothing leaves Ocufuse unless you export it."],["How do I send eye photos for a telehealth appointment?","Send eye photos for a telehealth appointment the way your clinic asks, usually through its patient portal or a secure message. Take each photo in even light, flash off, at a steady distance, with the views your clinician requests. Ocufuse can export a Doctor Brief with dated photos and notes."],["Can I track eye redness or dry eye symptoms with photos?","Ocufuse lets you photograph your eyes the same way each day and note symptoms such as redness, dryness or irritation, along with screen time, sleep and eye drops. It does not measure redness or judge severity. Your eye doctor uses the record as context alongside their own examination."],["Can an app diagnose eye problems?","Consumer phone apps cannot replace an eye examination. Apps that claim to diagnose or monitor a condition may be regulated as medical devices, and phone cameras are not calibrated instruments. Use apps to record and share information, and let an optometrist or ophthalmologist examine your eyes and make a diagnosis."],["What eye symptoms need urgent medical help?","Sudden double vision, sudden loss or dimming of vision, a suddenly drooping eyelid, new flashes or a curtain across vision, a painful red eye, and any eye injury need urgent medical care. Call your local emergency number or go to an emergency department rather than taking or comparing photos first."]]},{title:"Eye exercises",items:[["Do eye exercises improve vision?","Eye exercises do not improve nearsightedness, farsightedness, astigmatism or age-related reading problems, according to the American Academy of Ophthalmology. The main exception is convergence insufficiency, where clinician-supervised exercises have good evidence. Glasses, contact lenses or surgery remain the standard ways to correct refractive error."],["Can eye exercises fix nearsightedness?","Eye exercises cannot reverse nearsightedness (myopia). Myopia comes from the shape and length of the eye, which exercises do not change. The American Academy of Ophthalmology and major eye health organizations agree that glasses, contact lenses or refractive surgery correct it, and an eye doctor should manage any myopia control treatment."],["What are eye exercises used for?","Eye care professionals prescribe eye exercises mainly for convergence insufficiency and some focusing or eye teaming problems, and sometimes for recovery after surgery or certain injuries. Exercises are not a treatment for glaucoma, cataracts, macular degeneration or refractive error. Do exercises only as your eye care professional prescribes them."],["What are pencil push-ups?","Pencil push-ups are a home eye exercise for convergence insufficiency. You hold a pencil at arm's length, focus on a letter, and slowly bring it toward your nose while keeping it single. Clinicians prescribe the number of repetitions. In the CITT trial, office-based therapy outperformed pencil push-ups alone."],["What is a Brock string?","A Brock string is a cord with colored beads that eye care professionals use to train and check eye teaming. Holding one end at your nose, you focus on each bead and notice whether the strings appear to cross there. It is commonly prescribed in orthoptic and vision therapy programs."],["Is palming good for your eyes?","Palming means covering closed eyes with warm palms to rest them. It can feel relaxing, but there is no evidence that palming or the related Bates method improves eyesight, according to the American Academy of Ophthalmology. Palming is not a substitute for glasses, contact lenses or eye treatment."],["Can eye exercises help with needing reading glasses?","Eye exercises do not reverse presbyopia, the age-related loss of close focusing that leads to reading glasses, according to the American Academy of Ophthalmology. Presbyopia comes from the eye's lens becoming less flexible with age. Reading glasses, multifocal lenses, contact lenses or surgery are the standard ways to manage it."],["What is the Bates method?","The Bates method is an eye relaxation program developed by ophthalmologist William Bates in the early 1900s that claims to cure refractive errors without glasses. Techniques include palming and sunning. The American Academy of Ophthalmology states there is no evidence that the Bates method improves eyesight."],["What is an orthoptist?","An orthoptist is an eye care professional who specialises in disorders of eye movement and alignment, such as strabismus, amblyopia and convergence insufficiency. Orthoptists assess how the eyes work together, prescribe and supervise eye exercises, and often work alongside ophthalmologists in hospital eye departments, including in the NHS."],["How can Ocufuse help with prescribed eye exercises?","Ocufuse provides a Practice log for exercises your eye care professional prescribes. You record which exercise you did and when, and the log appears in your Doctor Brief for your next review. Ocufuse does not prescribe, adjust or teach exercises, so follow your clinician's instructions."]]},{title:"Digital eye strain",items:[["What is the 20-20-20 rule?","The 20-20-20 rule means every 20 minutes of screen use, you look at something 20 feet (about 6 metres) away for 20 seconds. The American Optometric Association recommends it to reduce digital eye strain by relaxing the focusing muscles and encouraging normal blinking during long periods of close work."],["Does the 20-20-20 rule work?","The 20-20-20 rule reduced digital eye strain and dry eye symptoms in a 2022 study of computer users who received regular break reminders. The benefit faded about one week after participants stopped taking breaks. Regular breaks help comfort but do not change eyesight or correct vision problems."],["What is digital eye strain?","Digital eye strain, also called computer vision syndrome, is a group of eye and vision symptoms from prolonged screen use. Common symptoms include eyestrain, headaches, blurred vision, dry eyes, and neck and shoulder pain. The American Optometric Association links risk to two or more hours of continuous screen use."]]},{title:"Vision therapy",items:[["What is vision therapy?","Vision therapy is a structured program of eye exercises and activities supervised by an optometrist or orthoptist to treat certain eye teaming and focusing problems. Sessions usually last 30 to 60 minutes once or twice a week, with exercises to practise at home between visits."],["Does vision therapy work?","Vision therapy has strong evidence for convergence insufficiency. In the CITT trial of children aged 9 to 17, office-based therapy succeeded in 73 percent of cases versus 35 percent with placebo. Evidence for most other uses is limited, and ophthalmology groups advise against vision therapy for learning disabilities."],["Can vision therapy help dyslexia or learning disabilities?","Vision therapy does not treat dyslexia or learning disabilities, according to a joint statement from the American Academy of Pediatrics, the American Academy of Ophthalmology and pediatric ophthalmology groups. Children with reading difficulties should still have an eye exam, alongside educational assessment, to rule out treatable vision problems."],["What is convergence insufficiency?","Convergence insufficiency is a condition where the eyes do not turn inward together easily for close work. It can cause eyestrain, headaches, double or blurred vision and losing your place when reading. Clinician-supervised vision therapy, often with home exercises, is the treatment with the strongest evidence."],["Who provides vision therapy?","Optometrists and orthoptists provide vision therapy, often in specialist clinics, and ophthalmologists diagnose and manage the underlying eye conditions. For example, NHS orthoptists at Cambridge University Hospitals supervise home exercises for convergence insufficiency with reviews every one to two weeks. Ask your eye doctor about a referral."],["Who is a good candidate for vision therapy?","Good candidates for vision therapy are people diagnosed with convergence insufficiency or certain focusing and eye teaming problems after a full eye examination. Cleveland Clinic notes the evidence mainly supports convergence insufficiency and accommodative dysfunction. Vision therapy is not recommended for learning disabilities or for correcting refractive error."],["Is vision therapy covered by insurance?","Vision therapy coverage varies by country, insurer and plan, and often depends on the diagnosis. Some plans cover treatment for a diagnosed condition such as convergence insufficiency but not other uses. Ask the clinic for the diagnosis and treatment codes, then confirm coverage with your insurer before starting."],["What is the difference between vision therapy and orthoptics?","Orthoptics is the assessment and non-surgical treatment of eye movement and alignment problems, usually by orthoptists, with evidence for convergence insufficiency. Behavioral vision therapy, offered by some optometrists, covers a broader range of goals. Ophthalmology and pediatric groups consider the evidence for many of those broader uses limited."],["How long does vision therapy take?","Vision therapy programs commonly last several weeks to a few months, depending on the condition and progress. The CITT trial for convergence insufficiency used a 12-week program of weekly office sessions with home practice. Your eye care professional sets the schedule and reviews progress at regular visits."]]},{title:"Eye conditions explained",items:[["What is amblyopia?","Amblyopia, often called lazy eye, is reduced vision in one eye caused by abnormal visual development in childhood. The brain favours the other eye. Treatment is most effective in young children and can include glasses, patching the stronger eye, or atropine eye drops, prescribed and monitored by an eye care professional."],["What is strabismus?","Strabismus is a misalignment of the eyes, where one eye turns in, out, up or down while the other looks straight ahead. It can be constant or come and go. Treatment depends on the cause and may include glasses, prism lenses, eye muscle surgery, or exercises for some types."],["What is accommodative dysfunction?","Accommodative dysfunction is difficulty adjusting the eyes' focus between distances or sustaining focus up close. It can cause blurred near vision, eyestrain and headaches during reading. It is diagnosed during an eye examination, and treatment may include glasses for close work or exercises prescribed by an optometrist or orthoptist."]]}],p=a.flatMap(o=>o.items);var e=n(r()),i={"Do eye exercises improve vision?":["/eye-exercises/","Eye exercises: what the research says"],"Can eye exercises fix nearsightedness?":["/eye-exercises/myths","Eye exercise myths"],"What are eye exercises used for?":["/eye-exercises/","Guide to eye exercises"],"What are pencil push-ups?":["/eye-exercises/pencil-push-ups-brock-string","Pencil push-ups and the Brock string"],"What is a Brock string?":["/eye-exercises/pencil-push-ups-brock-string","Pencil push-ups and the Brock string"],"Is palming good for your eyes?":["/eye-exercises/myths","Eye exercise myths"],"How can Ocufuse help with prescribed eye exercises?":["/eye-exercises/exercise-log","Eye exercise log"],"What is the 20-20-20 rule?":["/eye-exercises/20-20-20-rule","The 20-20-20 rule and digital eye strain"],"Does the 20-20-20 rule work?":["/eye-exercises/20-20-20-rule","What the research found"],"What is digital eye strain?":["/eye-exercises/20-20-20-rule","Digital eye strain explained"],"What is convergence insufficiency?":["/eye-exercises/convergence-insufficiency","Convergence insufficiency explained"],"Does vision therapy work?":["/eye-exercises/convergence-insufficiency","The CITT trial explained"],"How do I take a photo of my eye for my doctor?":["/blog/how-to-take-consistent-eye-photos","Full photo guide"],"Why do my eye photos look different every day?":["/blog/why-eye-photos-look-different-day-to-day","Why photos look different"],"Can eye exercises help with needing reading glasses?":["/eye-exercises/myths","Eye exercise myths"],"What is the Bates method?":["/eye-exercises/myths","The Bates method and palming"],"What is an orthoptist?":["/eye-exercises/convergence-insufficiency","How orthoptists treat convergence insufficiency"],"Who is a good candidate for vision therapy?":["/eye-exercises/convergence-insufficiency","Convergence insufficiency explained"],"How do I send eye photos for a telehealth appointment?":["/blog/how-to-take-consistent-eye-photos","How to take consistent eye photos"],"Can I track eye redness or dry eye symptoms with photos?":["/blog/why-eye-photos-look-different-day-to-day","Why photos look different day to day"],"Does Ocufuse use my photos to train AI?":["/privacy","Privacy policy"],"Can children use Ocufuse?":["/terms","Terms of use"],"What should I bring to an eye doctor appointment?":["/blog/preparing-for-an-eye-appointment-when-symptoms-come-and-go","Preparing for your appointment"]},l=[["American Academy of Ophthalmology: Vision training not proven to make vision sharper","https://www.aao.org/eye-health/tips-prevention/vision-training-not-proven-to-make-vision-sharper"],["American Academy of Ophthalmology: Can eye exercises improve my eyesight?","https://www.aao.org/eye-health/ask-ophthalmologist-q/can-eye-exercises-improve-my-eyesight"],["American Optometric Association: Computer vision syndrome","https://www.aoa.org/healthy-eyes/eye-and-vision-conditions/computer-vision-syndrome"],["College of Optometrists in Vision Development: What is vision therapy?","https://www.covd.org/page/vision_therapy"],["Convergence Insufficiency Treatment Trial (CITT) results summary","https://reviewofophthalmology.com/article/study-supports-therapy-for-children-with-ci"],["Cochrane: Treatments for convergence insufficiency compared","https://www.cochrane.org/evidence/CD006768_how-do-different-treatments-vision-disorder-convergence-insufficiency-compare-effectiveness"],["Talens-Estarelles et al. 2022: The effects of breaks on digital eye strain","https://research.aston.ac.uk/en/publications/the-effects-of-breaks-on-digital-eye-strain-dry-eye-and-binocular/"],["Cleveland Clinic: Vision therapy","https://my.clevelandclinic.org/health/treatments/vision-therapy"],["Cambridge University Hospitals NHS: Convergence insufficiency","https://www.cuh.nhs.uk/patient-information/convergence-insufficiency-ci/"],["Cochrane: Treatment of amblyopia with patching or drops","https://www.cochrane.org/evidence/CD006460_treatment-amblyopia-lazy-eye-patching-or-dropsdrug-treatment"],["National Eye Institute: Eye drops treat childhood eye disorder","https://www.nei.nih.gov/about/news-and-events/news/eye-drops-treat-childhood-eye-disorder"],["American Academy of Ophthalmology: Strabismus in children","https://www.aao.org/eye-health/diseases/strabismus-in-children"],["Penn Medicine: Strabismus","https://pennmedicine.org/for-patients-and-visitors/patient-information/conditions-treated-a-to-z/strabismus"]];function y(){return(0,e.jsxs)(c,{active:"faq",children:[(0,e.jsx)(h,{eyebrow:"FAQ",title:"Eye photos, eye exercises and vision therapy: 44 questions answered",lead:"Short, sourced answers about Ocufuse, taking eye photos for your doctor, eye exercises, digital eye strain, vision therapy and common eye conditions.",meta:"Last reviewed: 11 October 2026"}),(0,e.jsx)("section",{className:"doc",children:(0,e.jsxs)("div",{className:"wrap",children:[(0,e.jsxs)("nav",{className:"toc","aria-label":"Topics",children:[(0,e.jsx)("b",{children:"Topics"}),(0,e.jsxs)("ol",{children:[a.map(o=>(0,e.jsx)("li",{children:(0,e.jsx)("a",{href:"#"+t(o.title),children:o.title})},o.title)),(0,e.jsx)("li",{children:(0,e.jsx)("a",{href:"#sources",children:"Sources"})})]})]}),(0,e.jsxs)("div",{className:"prose faq-page",children:[(0,e.jsxs)("div",{className:"callout callout-note",children:[(0,e.jsx)("strong",{children:"Information, not medical advice"}),"Ocufuse is a journal, not a medical device. These answers summarise published guidance. Talk to your eye care professional about your own eyes, and see ",(0,e.jsx)("a",{href:"/safety",children:"warning signs that need urgent care"}),"."]}),a.map(o=>(0,e.jsxs)("section",{"aria-labelledby":t(o.title),children:[(0,e.jsx)("h2",{id:t(o.title),children:o.title}),o.items.map(([s,d])=>(0,e.jsxs)("div",{className:"qa",id:t(s),children:[(0,e.jsx)("h3",{children:s}),(0,e.jsx)("p",{children:d}),i[s]&&(0,e.jsx)("p",{className:"more-link",children:(0,e.jsx)("a",{href:i[s][0],children:i[s][1]})})]},s))]},o.title)),(0,e.jsx)("h2",{id:"sources",children:"Sources"}),(0,e.jsx)("ol",{className:"sources",children:l.map(([o,s])=>(0,e.jsx)("li",{children:(0,e.jsx)("a",{href:s,rel:"noopener",children:o})},s))})]})]})})]})}export{y as default};
